<script setup lang="ts">
import{computed,onMounted,onUnmounted,ref,watch}from 'vue';import ConsoleDialog from './ConsoleDialog.vue';import{useDispatchStore}from './stores/dispatch';import{blockingCurrent,demoBlocking,requirementLabel,blockingStateLabel,trafficEventLabel}from './blocking';import{resourceView}from './waiting';import{label}from './state';import{shortTime}from './dashboard';import type{TrafficRequest,BlockingPage,BlockingLink}from './types';
const props=defineProps<{request:TrafficRequest}>(),emit=defineEmits<{close:[];locate:[id:string];task:[id:string]}>(),store=useDispatchStore();const data=ref<BlockingPage|null>(null),busy=ref(false),error=ref('');let epoch=0,timer:ReturnType<typeof setInterval>|undefined;
const context=computed(()=>[store.demoMode,store.adapterIdentity?.sha256,store.snapshot?.map?.id,store.snapshot?.map?.version,store.snapshot?.map?.definitionHash,props.request.taskId,props.request.stepId].join('|'));
const live=computed(()=>blockingCurrent(data.value,store.snapshot,props.request.taskId,props.request.stepId,store.now));
async function load(){if(!store.fresh||busy.value)return;const mine=++epoch,ctx=context.value;busy.value=true;error.value='';try{const map=store.snapshot?.map;const response=store.demoMode?demoBlocking(store.snapshot!,props.request):await store.api<BlockingPage>('/api/traffic/blocking',{taskId:props.request.taskId,stepId:props.request.stepId,expectedMapId:map?.id??null,expectedMapVersion:map?.version??null,expectedMapDefinitionHash:map?.definitionHash??null});if(mine===epoch&&ctx===context.value)data.value=response;}catch(e){if(mine===epoch){data.value=null;error.value=String(e);}}finally{if(mine===epoch)busy.value=false;}}
watch(context,()=>{++epoch;busy.value=false;data.value=null;void load();});watch(()=>store.fresh,f=>{if(!f){++epoch;data.value=null;busy.value=false;}else void load();});
function canLocate(l:BlockingLink){const m=store.snapshot?.map,n=data.value?.detail.nodes.find(n=>n.taskId===l.fromTaskId&&n.stepId===l.fromStepId);return live.value&&l.kind==='Resource'&&l.mapId===m?.id&&l.mapVersionId===m?.version&&n?.mapId===m?.id&&n?.mapVersionId===m?.version&&!!resourceView(m,l.resourceId??'');}
async function locate(l:BlockingLink){if(!canLocate(l)||!l.resourceId)return;emit('locate',l.resourceId);}
async function task(id:string){if(!live.value)return;emit('task',id);}
onMounted(()=>{void load();timer=setInterval(()=>void load(),5000);});onUnmounted(()=>{++epoch;clearInterval(timer);});
</script>
<template><ConsoleDialog title="阻塞链详情 · 释放条件与路权事件" wide @close="emit('close')"><section class="blocking-detail"><p>原任务 {{request.taskId}} · 步骤 {{request.stepId}}</p><p class="inline-warning">{{store.demoMode?'浏览器合成示例。':'原后台只读快照。'}}释放条件表示核验要求，不是放行许可；当前页不解锁、不改优先级、不派车。</p><button :disabled="busy||!store.fresh" @click="load">刷新阻塞链</button><p v-if="error" role="status">{{error}}</p><template v-if="data"><p>观察 {{shortTime(data.detail.capturedAt)}} · {{live?'有效观察':'观察失效，联动已禁用'}} · {{data.detail.message}}</p><p v-if="data.detail.truncated" class="inline-warning">链路达到范围限制或信息不足，不能视为完整阻塞链。</p><p v-if="data.detail.eventsTruncated" class="inline-warning">关联历史仅显示最近50条，不能当作全部路权历史。</p><p>{{data.detail.cycleObserved?'观察到循环依赖（不是自动判定死锁）。':'当前展开范围未观察到循环；不排除未展开的依赖。'}}</p>
<h3>等待 → 资源 → 占用步骤</h3><div class="blocking-links"><article v-for="(l,i) in data.detail.links" :key="i"><b>{{l.fromTaskId}} / {{l.fromStepId}}</b><p v-if="l.kind==='Resource'">等待资源 {{l.resourceId}} → {{l.toTaskId}} / {{l.toStepId}} · 车辆 {{l.vehicleId}} <button :disabled="!canLocate(l)" @click="locate(l)">定位阻塞 {{l.resourceId}}</button><small>{{l.heartbeatExpired?'心跳过期，占用仍保留。':'当前占用归属。'}} {{l.mapId||'地图未知'}} / {{l.mapVersionId||'版本未知'}}</small></p><p v-else>同一任务另一等待步骤 → {{l.toTaskId}} / {{l.toStepId}}（不是资源占用边）</p></article><p v-if="!data.detail.links.length">未返回当前确认的阻塞边；不能据此判断可以派发或释放。</p></div>
<h3>占用状态与释放核验要求</h3><details v-for="n in data.detail.nodes" :key="n.taskId+n.stepId" open><summary>{{n.taskId}} / {{n.stepId}} · {{n.vehicleId}} · {{blockingStateLabel(n.state)}}</summary><p>任务 {{label(n.taskStage)}} · 步骤 {{label(n.stepStatus)}} · 原命令 {{label(n.commandStatus)}} <button :disabled="!live||!n.taskStage" @click="task(n.taskId)">查看任务 {{n.taskId}}</button></p><p>{{n.reason}}</p><p v-if="n.missingEvidence" class="inline-warning">原归属记录不完整，不能补造路线、现场状态或释放结论。</p><ul><li v-for="r in n.releaseRequirements" :key="r.id"><b>{{r.text}} · {{requirementLabel(r.state)}}</b><p>{{r.evidence}}</p></li></ul></details>
<h3>最近关联路权事件</h3><ol class="blocking-events"><li v-for="e in data.detail.events" :key="e.eventId"><time>{{shortTime(e.occurredAt)}}</time> · {{trafficEventLabel(e.kind)}}（{{e.kind}}） · {{e.taskId}} / {{e.stepId}}<p>{{e.resourceIds.join('、')}} · {{e.reason}}</p></li></ol><p v-if="!data.detail.events.length">未返回关联事件；不代表没有发生，也不使用全场同名资源的事件补齐。</p></template><p v-else-if="!error">{{busy?'正在读取原后台阻塞关系…':'尚无有效观察，请连接后台后刷新。'}}</p></section></ConsoleDialog></template>
<style scoped>.blocking-detail{font-size:12px;line-height:1.9}.blocking-detail p{margin:10px 0;overflow-wrap:anywhere}.blocking-detail h3{margin:20px 0 10px;color:#cbe4f5}.blocking-detail article,.blocking-detail details{border:1px solid #304765;padding:12px;margin:10px 0}.blocking-detail small{display:block;color:#9eb7ce}.blocking-detail summary{cursor:pointer;color:#bce3f3}.blocking-detail button{margin:5px}.blocking-detail li{margin:8px 0}.blocking-events{padding-left:20px;max-height:380px;overflow:auto}.blocking-events time{color:#79bddb}</style>
